"""Individually authored problem records, not extracted by keyword classification."""
from pathlib import Path
import json
W=Path(__file__).resolve().parents[1]; P=W/'parts/root'
I={x['id']:x for x in json.loads((P/'items.json').read_text())}; R=[]
def problem(n,title,items,his,today,art,why,worth,refs):
 ids=[f'SA06-{i}' for i in items]
 R.append(dict(id=f'MP-SA06-{n}',title=title,occurrences=[dict(item=i,cote=I[i]['cote'],scans=I[i]['scans'],lines=I[i]['lines']) for i in ids],as_he_states=his,plausible_today=today,state_of_art='Assessment 19 November 2026. '+art,why_open=why,worth=worth,refs=refs))

